import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Button, Menu, Dropdown, Icon, Row, Col, Input, Alert, Table } from 'antd'
import LayoutContent from '../../../components/utility/layoutContent'
import LayoutContentWrapper from '../../../components/utility/layoutWrapper'
import PartnerStyleWrapper from './partner.style'
import partnerAction from '../../redux/partner/actions'
import moment from 'moment'
import XLSX from 'xlsx'
import downloader from '../../../helpers/downloader'
import { dateGenerator } from '../../../helpers/utility'
import NewPartner from './addNewPartner'
import DemoDelay from './demoDelay'
import PermissionChecker from '../../../components/permissionChecker'

const SEARCH_STORAGE_KEY = 'partner_list_search'

const { getPartnerList, resetState } = partnerAction

class PartnerTableList extends PureComponent {
  constructor (props) {
    super(props)
    const savedSearch = localStorage.getItem(SEARCH_STORAGE_KEY) || ''
    this.state = {
      demoDelayVisible: false,
      dataSource: [],
      filteredData: [],
      searchInput: savedSearch,
      loading: false,
      error: false,
      statusAddNewPartner: '',
      dataAddPartner: {},
      pageSize: 10
    }
  }

  getColumns = () => {
    return [
      {
        title: 'Action',
        key: 'action',
        width: 110,
        render: (text, record) => (
          <i
            className='fa fa-eye'
            style={{ color: '#424242', fontSize: '18px', cursor: 'pointer' }}
            onClick={() => this.viewDetail(record)}
          />
        )
      },
      {
        title: 'Company Code',
        dataIndex: 'code',
        key: 'code',
        sorter: (a, b) => (a.code || '').localeCompare(b.code || '')
      },
      {
        title: 'Company Name',
        dataIndex: 'name',
        key: 'name',
        sorter: (a, b) => (a.name || '').localeCompare(b.name || '')
      },
      {
        title: 'Status',
        dataIndex: 'status',
        key: 'status',
        sorter: (a, b) => (a.status || '').localeCompare(b.status || '')
      },
      {
        title: 'Created At',
        dataIndex: 'created_at',
        key: 'created_at',
        render: (text) => text ? moment(text).format('DD MMMM YYYY') : '',
        sorter: (a, b) => moment(a.created_at).unix() - moment(b.created_at).unix()
      },
      {
        title: 'Updated At',
        dataIndex: 'updated_at',
        key: 'updated_at',
        render: (text) => text ? moment(text).format('DD MMMM YYYY') : '',
        sorter: (a, b) => moment(a.updated_at).unix() - moment(b.updated_at).unix()
      }
    ]
  }

  applySearch = (data, searchValue) => {
    if (!searchValue) return data
    const searchLower = searchValue.toLowerCase()
    return data.filter(record =>
      Object.values(record).some(val =>
        val && val.toString().toLowerCase().includes(searchLower)
      )
    )
  }

  viewDetail = (data) => {
    this.props.history.push(`/partner/${data.id}`, { params: { partnerId: data.id, partnerCode: data.code } })
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { partnerListData, partnerListStatus, statusAddNewPartner, dataAddPartner } = nextProps.partnerData
    if (statusAddNewPartner === 'success' && statusAddNewPartner !== undefined) {
      this.setState({ statusAddNewPartner, dataAddPartner })
    }
    if (statusAddNewPartner !== 'success' && statusAddNewPartner !== undefined) {
      this.setState({ statusAddNewPartner })
    }
    if (partnerListStatus !== 'success') {
      this.setState({ error: true })
    }

    if (partnerListData) {
      const data = partnerListData || []
      this.setState({
        dataSource: data,
        filteredData: this.applySearch(data, this.state.searchInput),
        loading: false
      })
    } else {
      this.setState({
        dataSource: [],
        filteredData: [],
        loading: false
      })
    }
  }

  componentDidMount () {
    this.setState({ loading: true })
    this.props.getPartnerList()
  }

  componentWillUnmount () {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.resetState()
  }

  resetState = () => {
    this.props.resetState()
  }

  exportToExcel () {
    const { filteredData } = this.state
    const exportData = filteredData.map(row => ({
      'Company Code': row.code || '',
      'Company Name': row.name || '',
      'Status': row.status || '',
      'Created At': row.created_at && row.created_at.Time ? moment(row.created_at.Time).format('YYYY-MM-DD') : '',
      'Updated At': row.updated_at && row.updated_at.Time ? moment(row.updated_at.Time).format('YYYY-MM-DD') : ''
    }))

    const worksheet = XLSX.utils.json_to_sheet(exportData)
    const workbook = XLSX.utils.book_new()
    XLSX.utils.book_append_sheet(workbook, worksheet, 'Partner List')
    const xlsxContent = XLSX.write(workbook, { bookType: 'xlsx', type: 'base64' })
    const params = {
      fileName: 'partner_list_' + dateGenerator()
    }
    downloader(params, xlsxContent)
  }

  handleClearFilter = () => {
    localStorage.removeItem(SEARCH_STORAGE_KEY)
    this.setState({
      searchInput: '',
      filteredData: this.state.dataSource
    })
  }

  onFilterChange = (val) => {
    const searchValue = val.target.value
    localStorage.setItem(SEARCH_STORAGE_KEY, searchValue)
    this.setState({
      searchInput: searchValue,
      filteredData: this.applySearch(this.state.dataSource, searchValue)
    })
  }

  changePaginationSize = (size) => {
    this.setState({ pageSize: Number(size) })
  }

  handleCreatePartner = () => {
    this.setState({ isNewPartnerModalOpen: true })
  }

  partnerModalClose = () => {
    this.setState({ isNewPartnerModalOpen: false })
  }

  demoDelayClose = () => {
    this.setState({ demoDelayVisible: false })
  }

  onCreateDelay = () => {
    this.setState({ demoDelayVisible: true })
  }

  render () {
    const { filteredData, searchInput, statusAddNewPartner, dataAddPartner, loading, pageSize } = this.state
    const { permissions } = this.props
    const menu = (
      <Menu onClick={this.exportToExcel.bind(this)}>
        <Menu.Item key='1'><Icon type='right-circle-o' /> Excel</Menu.Item>
      </Menu>
    )
    const checkPermissionAddPartner = permissions.filter(value => value === 'ops.create_new_partner')
    const menuPagination = (
      <Menu>
        <Menu.Item key='1' onClick={() => this.changePaginationSize('50')}>50</Menu.Item>
        <Menu.Item key='2' onClick={() => this.changePaginationSize('100')}>100</Menu.Item>
        <Menu.Item key='3' onClick={() => this.changePaginationSize('200')}>200</Menu.Item>
        <Menu.Item key='4' onClick={() => this.changePaginationSize('300')}>300</Menu.Item>
        <Menu.Item key='5' onClick={() => this.changePaginationSize('400')}>400</Menu.Item>
        <Menu.Item key='6' onClick={() => this.changePaginationSize('500')}>500</Menu.Item>
      </Menu>
    )
    return (
      <PartnerStyleWrapper>
        <LayoutContentWrapper className='content-wrapper'>
          {statusAddNewPartner === 'success' && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message={`${dataAddPartner.name} is successful added`}
                  type='success'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          {(statusAddNewPartner !== 'success' && statusAddNewPartner !== '') && (
            <Row className='error-row'>
              <Col span={24}>
                <Alert
                  className='alert'
                  message='Failed to add new partner'
                  type='error'
                  closeText='Close'
                />
              </Col>
            </Row>
          )}
          <LayoutContent className='content'>
            <Row gutter={16}>
              <NewPartner
                isOpen={this.state.isNewPartnerModalOpen}
                triggerClose={this.partnerModalClose}
              />
              <DemoDelay
                isOpen={this.state.demoDelayVisible}
                triggerClose={this.demoDelayClose}
              />
              <Col className='gutter-row-export-excel' span={24}>
                <h3>Partner List</h3>
                <div className='btn-container'>
                  {
                    checkPermissionAddPartner.length > 0 && (
                      <Button
                        className='btn-filter'
                        onClick={this.handleCreatePartner}
                      >
                        <i className='fas fa-user-plus' /> Add Partner
                      </Button>
                    )
                  }
                  <Button
                    className='btn-filter'
                    onClick={this.handleClearFilter}
                  >
                    <Icon type='filter' /> Clear filters
                  </Button>
                  <Input
                    className='input-filter'
                    value={searchInput}
                    type='text'
                    id='filter-text-box'
                    placeholder='Search...'
                    onInput={val => this.onFilterChange(val)}
                  />
                  <PermissionChecker permissionSetter='ops.download_partner_list' permissionGetter={permissions}>
                    <Dropdown overlay={menu}>
                      <Button>
                        Export to <Icon type='down' />
                      </Button>
                    </Dropdown>
                    <Dropdown overlay={menuPagination}>
                      <Button className='btn-page-size'>Page size <Icon type='down' /></Button>
                    </Dropdown>
                  </PermissionChecker>
                </div>
              </Col>
            </Row>
            <Table
              columns={this.getColumns()}
              dataSource={filteredData}
              rowKey={(record) => record.id || Math.random()}
              pagination={{
                pageSize: pageSize,
                showSizeChanger: true,
                showQuickJumper: true,
                showTotal: (total, range) => `[${range[0]}-${range[1]}] of ${total} items`
              }}
              scroll={{ x: true, y: true }}
              loading={loading}
              locale={{
                emptyText: 'Data is empty :('
              }}
              style={{ marginTop: '16px' }}
            />
          </LayoutContent>
        </LayoutContentWrapper>
      </PartnerStyleWrapper>
    )
  }
}

PartnerTableList.propTypes = {
  partnerData: PropTypes.object.isRequired,
  dataProfile: PropTypes.object.isRequired
}

PartnerTableList.defaultProps = {
  partnerData: {},
  dataProfile: {}
}

export default connect(
  state => ({
    partnerData: state.Partner,
    dataProfile: state.Auth.profile
  }),
  { getPartnerList, resetState }
)(PartnerTableList)
