import React, { PureComponent } from 'react'
import { connect } from 'react-redux'
import { Modal, Button, Form, Input, Row, Icon, Select, Col } from 'antd'
import NewPartnerStyled from './newPartner.style.js'

const FormItem = Form.Item
const Option = Select.Option

class demoDelay extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      isVisible: false,
      submitting: false,
      value: '',
      nextState: 1
    }
  }

  componentWillReceiveProps (nextProps) {
    const { isOpen } = nextProps
    this.setState({ isVisible: isOpen })
  }

  async validateForm () {
    return new Promise(resolve => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const { form } = this.props
    const data = form.getFieldsValue()
    this.setState({
      ...data,
      nextState: 3
    })
  };

  handleCancel = e => {
    this.props.form.resetFields()
    this.props.triggerClose()
    this.setState({
      nextState: 1
    })
  };

  validateNumber (event) {
    var key = window.event ? event.keyCode : event.which
    if (event.keyCode === 8 || event.keyCode === 46) {
      return true
    } else if (key < 48 || key > 57) {
      return false
    } else {
      return true
    }
  }

  onConnectionSelect = val => {
    this.setState({ connection: val })
  };

  onNextClick = () => {
    const { form } = this.props
    const data = form.getFieldsValue()
    this.setState({
      ...data,
      nextState: 2
    })
  };

  render () {
    const { isVisible } = this.state
    const { form } = this.props
    const { getFieldDecorator } = form
    return (
      <NewPartnerStyled>
        <Modal
          closable={false}
          maskClosable={false}
          title={null}
          visible={isVisible}
          footer={null}
          className='new-partner-modal'
        >
          <center>
            <h2 style={{ marginBottom: '30px' }}>Flight Delay Product</h2>
          </center>
          <Row>
            {this.state.nextState === 3 && (
              <center>
                <p style={{ color: 'green' }}>
                  Product is created successfully
                </p>
                <p>Product Name : {this.state.product_name}</p>
                <p>Delay in minutes : {this.state.delay}</p>
                <p>Currency : {this.state.currency}</p>
                <p>Premium : {this.state.premium}</p>
                <p>Claim Amount : {this.state.claim_amount}</p>
                <p>Insurance : {this.state.insurance_type}</p>
                <p>Connection Type : {this.state.connection_type}</p>
              </center>
            )}
            <Form onSubmit={this.onSubmit}>
              {this.state.nextState === 1 && (
                <div>
                  <Col xs={12}>
                    <label className='custom-label'>Name of the product</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('product_name', {
                        rules: [
                          {
                            required: true,
                            message: 'Product name can not be empty'
                          }
                        ]
                      })(
                        <Input
                          size='default'
                          className='input-box'
                          placeholder='Name of the product'
                        />
                      )}
                    </FormItem>
                  </Col>
                  <Col xs={12}>
                    <label className='custom-label'>Delay in Minutes</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('delay', {
                        rules: [
                          {
                            required: true,
                            message: 'Delay can not be empty'
                          }
                        ]
                      })(
                        <Select>
                          <Option value={0} selected>
                            No Delay
                          </Option>
                          <Option value={30}>30 Minutes</Option>
                          <Option value={60}>1 Hour</Option>
                          <Option value={120}>2 Hours </Option>
                          <Option value={150}>2 Hours 30 Minutes</Option>
                          <Option value={180}>3 Hours </Option>
                          <Option value={210}>3 Hours 30 Minutes</Option>
                          <Option value={240}>4 Hours</Option>
                          <Option value={270}>4 Hours 30 Minutes</Option>
                          <Option value={300}>5 Hours</Option>
                          <Option value={360}>6 Hours</Option>
                          <Option value={420}>7 Hours</Option>
                          <Option value={480}>8 Hours</Option>
                        </Select>
                      )}
                    </FormItem>
                  </Col>
                  <Col xs={12}>
                    <label className='custom-label'>Currency</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('currency', {
                        rules: [
                          {
                            required: true,
                            message: 'Currency can not be empty'
                          }
                        ],
                        setFieldsValue: this.state.value
                      })(
                        <Select>
                          <Option value='IDR'>IDR</Option>
                          <Option value='VND'>VND</Option>
                          <Option value='THB'>THB</Option>
                        </Select>
                      )}
                    </FormItem>
                  </Col>
                  <Col xs={12}>
                    <label className='custom-label'>Premium</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('premium', {
                        rules: [
                          {
                            required: true,
                            message: 'Premium can not be empty'
                          }
                        ]
                      })(
                        <Input
                          size='default'
                          className='input-box'
                          placeholder='Premium'
                        />
                      )}
                    </FormItem>
                  </Col>
                  <Col xs={12}>
                    <label className='custom-label'>Claim Amount</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('claim_amount', {
                        rules: [
                          {
                            required: true,
                            message: 'Amount can not be empty'
                          }
                        ]
                      })(
                        <Input
                          size='default'
                          className='input-box'
                          placeholder='Claim Amount'
                        />
                      )}
                    </FormItem>
                  </Col>
                </div>
              )}
              {this.state.nextState === 2 && (
                <div>
                  <Col xs={12}>
                    <label className='custom-label'>Select Insurance</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('insurance_type', {
                        rules: [
                          {
                            required: true,
                            message: 'Insurance type can not be empty'
                          }
                        ]
                      })(
                        <Select>
                          <Option value='AIA (TH)'>AIA (TH)</Option>
                          <Option value='AIA (VN)'>AIA (VN)</Option>
                          <Option value='Allianz insurance (ID)'>
                            Allianz insurance (ID)
                          </Option>
                          <Option value='AXA (TH)'>AXA (TH)</Option>
                          <Option value='Aao Viet (VN)'>Bao Viet (VN)</Option>
                          <Option value='BUPA Insurance (TH)'>
                            BUPA Insurance (TH)
                          </Option>
                          <Option value='Chubb insurance (ID)'>
                            Chubb insurance (ID)
                          </Option>
                          <Option value='Chubb insurance / ACE (VN)'>
                            Chubb insurance / ACE (VN)
                          </Option>
                          <Option value='Chubb insurance (TH)'>
                            Chubb insurance (TH)
                          </Option>
                          <Option value='Mega Insurance (ID)'>
                            Mega Insurance (ID)
                          </Option>
                          <Option value='Pacific Cross (TH)'>
                            Pacific Cross (TH)
                          </Option>
                          <Option value='PVI Sun (VN)'>PVI Sun (VN)</Option>
                          <Option value='Simasnet Insurance (ID)'>
                            Simasnet Insurance (ID)
                          </Option>
                          <Option value='Thai Vivat (TH)'>
                            Thai Vivat (TH)
                          </Option>
                          <Option value='Tugu insurance (ID)'>
                            Tugu insurance (ID)
                          </Option>
                        </Select>
                      )}
                    </FormItem>
                  </Col>
                  <Col xs={12}>
                    <label className='custom-label'>Connection Type</label>
                  </Col>
                  <Col xs={12}>
                    <FormItem style={{ fontSize: '11px' }}>
                      {getFieldDecorator('connection_type', {
                        rules: [
                          {
                            required: true,
                            message: 'Connection Type can not be empty'
                          }
                        ]
                      })(
                        <Select onSelect={this.onConnectionSelect}>
                          <Option value='csv'>CSV</Option>
                          <Option value='api'>API</Option>
                        </Select>
                      )}
                    </FormItem>
                  </Col>
                  {this.state.connection === 'csv' && (
                    <div>
                      <Col xs={12}>
                        <label className='custom-label'>Email</label>
                      </Col>
                      <Col xs={12}>
                        <FormItem style={{ fontSize: '11px' }}>
                          {getFieldDecorator('email', {
                            rules: [
                              {
                                required: true,
                                message: 'email can not be empty'
                              }
                            ]
                          })(
                            <Input
                              size='default'
                              className='input-box'
                              placeholder='Email'
                            />
                          )}
                        </FormItem>
                      </Col>
                    </div>
                  )}
                  {this.state.connection === 'api' && (
                    <div>
                      <Col xs={12} />
                      <Col xs={12}>
                        <p>
                          <Icon type='check-circle' /> API Sharing Enable
                        </p>
                      </Col>
                    </div>
                  )}
                </div>
              )}
              <div style={{ textAlign: 'right' }}>
                {(this.state.nextState === 1 || this.state.nextState === 2) && (
                  <Button key='back' onClick={this.handleCancel}>
                    Cancel
                  </Button>
                )}
                {this.state.nextState === 1 && (
                  <Button
                    onClick={this.onNextClick}
                    type='primary'
                    style={{ marginLeft: '10px' }}
                  >
                    Next
                  </Button>
                )}
                {this.state.nextState === 2 && (
                  <Button
                    onClick={this.onSubmit}
                    type='primary'
                    style={{ marginLeft: '10px' }}
                  >
                    Submit
                  </Button>
                )}
                {this.state.nextState === 3 && (
                  <center>
                    <Button
                      key='back'
                      onClick={this.handleCancel}
                      style={{ marginTop: '20px' }}
                    >
                      Close
                    </Button>
                  </center>
                )}
              </div>
            </Form>
          </Row>
        </Modal>
      </NewPartnerStyled>
    )
  }
}

const WrappedForm = Form.create({})(demoDelay)

export default connect(
  state => ({}),
  {}
)(WrappedForm)
