import React, { PureComponent } from 'react'
import PropTypes from 'prop-types'
import { connect } from 'react-redux'
import { Modal, Button, Form, Input } from 'antd'
import partnerAction from '../../redux/partner/actions'
import NewPartnerStyled from './newPartner.style.js'
import validator from '../../../helpers/validator'

const FormItem = Form.Item
const { addPartner } = partnerAction

class AddNewPartner extends PureComponent {
  constructor (props) {
    super(props)
    this.state = {
      isVisible: false,
      submitting: false,
      value: ''
    }
    this.onChange = this.onChange.bind(this)
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const { isOpen } = nextProps
    this.setState({ isVisible: isOpen })
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    this.setState({ submitting: true })
    const valid = await this.validateForm()
    if (!valid) {
      this.setState({ submitting: false })
      return
    }
    const { form } = this.props
    const data = form.getFieldsValue()
    const payload = {
      name: data.name,
      contact_name: data.contact,
      contact_phone: Number(data.phone),
      contact_email: data.email,
      send_secret: false
    }
    setTimeout(() => {
      this.setState({ submitting: false })
      this.props.triggerClose()
      this.props.addPartner({ payload })
      this.props.form.resetFields()
    }, 1000)
  }

    handleCancel = e => {
      this.props.form.resetFields()
      this.props.triggerClose()
    }

    validateNumber (event) {
      var key = window.event ? event.keyCode : event.which
      if (event.keyCode === 8 || event.keyCode === 46) {
        return true
      } else if (key < 48 || key > 57) {
        return false
      } else {
        return true
      }
    }

    onChange (e) {
      const re = /^[0-9\b]+$/
      if (e.target.value === '' || re.test(e.target.value)) {
        this.setState({ value: e.target.value })
      }
    }

    render () {
      const { isVisible, submitting } = this.state
      const { form } = this.props
      const { getFieldDecorator } = form
      return (
        <NewPartnerStyled>
          <Modal
            closable={false}
            maskClosable={false}
            title={'Add new partner'}
            visible={isVisible}
            footer={null}
            className='new-partner-modal'
          >
            <Form onSubmit={this.onSubmit}>
              <label className='custom-label'>Company name</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('name', {
                  rules: [
                    { required: true, message: 'Company name can not be empty' }
                  ]
                })(
                  <Input size='default' className='input-box' placeholder='Company name' />
                )}
              </FormItem>
              <label className='custom-label'>Contact name</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('contact', {
                  rules: [{
                    required: true, message: 'Contact name can not be empty'
                  }]
                })(
                  <Input size='default' className='input-box' placeholder='Contact name' />
                )}
              </FormItem>
              <label className='custom-label'>Contact Phone</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('phone', {
                  rules: [
                    { required: true, message: 'Phone can not be empty' },
                    { validator: validator.checkPhone }
                  ],
                  setFieldsValue: this.state.value
                })(
                  <Input size='default' className='input-box' placeholder='Contact phone' />
                )}
              </FormItem>
              <label className='custom-label'>Contact Email</label>
              <FormItem style={{ fontSize: '11px' }}>
                {getFieldDecorator('email', {
                  rules: [{
                    type: 'email', message: 'The input is not valid E-mail!'
                  }, {
                    required: true, message: 'Please input your E-mail!'
                  }]
                })(
                  <Input size='default' className='input-box' placeholder='Contact email' />
                )}
              </FormItem>
              <div style={{ textAlign: 'right' }}>
                <Button key='back' onClick={this.handleCancel}>Cancel</Button>
                <Button
                  key='submit'
                  type='primary'
                  htmlType='submit'
                  loading={submitting}
                  style={{ marginLeft: '10px' }}
                >
                                Submit
                </Button>
              </div>
            </Form>
          </Modal>
        </NewPartnerStyled>
      )
    }
}

AddNewPartner.propTypes = {
  isOpen: PropTypes.bool
}

AddNewPartner.defaultProps = {
  isOpen: false
}

const WrappedForm = Form.create({})(AddNewPartner)

export default connect(
  state => ({
    partnerGroups: state.PartnerGroups
  }),
  { addPartner }
)(WrappedForm)
